import { createContext, useContext, useMemo, useRef } from 'react';

const OverflowItemsShareContext = createContext(null);

let memberSeq = 0;
const createMemberId = () => {
  memberSeq += 1;
  return `oi-share-${memberSeq}`;
};

const getItemToken = item => {
  if (item == null) {
    return '';
  }
  if (typeof item !== 'object') {
    return String(item);
  }
  if (item.key != null) {
    return `k:${item.key}`;
  }
  if (item.id != null) {
    return `i:${item.id}`;
  }
  if (item.label != null) {
    return `l:${item.label}`;
  }
  if (item.children != null && (typeof item.children === 'string' || typeof item.children === 'number')) {
    return `c:${item.children}`;
  }
  return '?';
};

/**
 * 构建 Share 分桶签名。有 shareKey 时以其为主；否则从 items 标识推导。
 */
export const buildShareSignature = ({ shareKey, items, itemCount, gap = 8, strategy = 'asc', safetyGap = 2, expandHysteresis = 16 } = {}) => {
  const config = `g:${gap}|s:${strategy}|sg:${safetyGap}|eh:${expandHysteresis}|n:${itemCount}`;
  if (shareKey != null && shareKey !== '') {
    return `key:${shareKey}|${config}`;
  }
  const list = Array.isArray(items) ? items : [];
  const tokens = list.map(getItemToken).join(',');
  return `items:${tokens}|${config}`;
};

const createShareStore = () => {
  const buckets = new Map();

  const getBucket = signature => {
    let bucket = buckets.get(signature);
    if (!bucket) {
      bucket = {
        memberIds: [],
        callbacks: new Map(),
        leaderId: null,
        state: null
      };
      buckets.set(signature, bucket);
    }
    return bucket;
  };

  const notifyState = (bucket, state) => {
    bucket.callbacks.forEach(cb => {
      if (typeof cb.onStateChange === 'function') {
        cb.onStateChange(state);
      }
    });
  };

  const setLeader = (bucket, leaderId) => {
    const prev = bucket.leaderId;
    bucket.leaderId = leaderId;
    if (prev && prev !== leaderId) {
      const prevCb = bucket.callbacks.get(prev);
      if (prevCb?.onRoleChange) {
        prevCb.onRoleChange('follower');
      }
    }
    if (leaderId) {
      const nextCb = bucket.callbacks.get(leaderId);
      if (nextCb?.onRoleChange) {
        nextCb.onRoleChange('leader');
      }
    }
  };

  return {
    register(signature, memberId, { onRoleChange, onStateChange } = {}) {
      const bucket = getBucket(signature);
      if (!bucket.memberIds.includes(memberId)) {
        bucket.memberIds.push(memberId);
      }
      bucket.callbacks.set(memberId, { onRoleChange, onStateChange });

      const isLeader = bucket.leaderId == null;
      if (isLeader) {
        bucket.leaderId = memberId;
      }

      const role = bucket.leaderId === memberId ? 'leader' : 'follower';
      if (typeof onRoleChange === 'function') {
        onRoleChange(role);
      }
      if (bucket.state && typeof onStateChange === 'function') {
        onStateChange(bucket.state);
      }

      return {
        role,
        state: bucket.state,
        unregister() {
          const current = buckets.get(signature);
          if (!current) {
            return;
          }
          current.memberIds = current.memberIds.filter(id => id !== memberId);
          current.callbacks.delete(memberId);

          if (current.leaderId === memberId) {
            const nextLeader = current.memberIds[0] || null;
            current.leaderId = null;
            if (nextLeader) {
              setLeader(current, nextLeader);
            }
          }

          if (current.memberIds.length === 0) {
            buckets.delete(signature);
          }
        }
      };
    },

    publish(signature, state) {
      const bucket = buckets.get(signature);
      if (!bucket) {
        return;
      }
      bucket.state = state;
      notifyState(bucket, state);
    },

    getState(signature) {
      return buckets.get(signature)?.state || null;
    },

    getLeaderId(signature) {
      return buckets.get(signature)?.leaderId || null;
    }
  };
};

/**
 * 共享测宽上下文。同签名实例只保留一个 Leader 测宽，其余消费结果。
 * 约定：同 bucket 内容器宽度一致（如表格操作列）。
 */
export const OverflowItemsShare = ({ children }) => {
  const storeRef = useRef(null);
  if (!storeRef.current) {
    storeRef.current = createShareStore();
  }
  return <OverflowItemsShareContext.Provider value={storeRef.current}>{children}</OverflowItemsShareContext.Provider>;
};

export const useOverflowItemsShareStore = () => useContext(OverflowItemsShareContext);

export const useShareMemberId = () => {
  const idRef = useRef(null);
  if (!idRef.current) {
    idRef.current = createMemberId();
  }
  return idRef.current;
};

export const useShareSignature = ({ shareKey, items, itemCount, gap, strategy, safetyGap, expandHysteresis, enabled }) => {
  const store = useOverflowItemsShareStore();
  return useMemo(() => {
    if (!store || enabled === false) {
      return null;
    }
    const hasShareKey = shareKey != null && shareKey !== '';
    const hasItems = Array.isArray(items);
    if (!hasShareKey && !hasItems) {
      return null;
    }
    return buildShareSignature({
      shareKey,
      items,
      itemCount,
      gap,
      strategy,
      safetyGap,
      expandHysteresis
    });
  }, [store, shareKey, items, itemCount, gap, strategy, safetyGap, expandHysteresis, enabled]);
};

export default OverflowItemsShare;
